import { useRef, useState } from 'react'
import {
  getWithdrawList,
  getWithdrawDetail,
  confirmPaymentWithdraw,
  OrderManagementTypes
} from '@/apis/admin/order-management'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProFormInstance, ProColumns } from '@ant-design/pro-components'
import {
  Button,
  message,
  Tag,
  Space,
  Tooltip,
  Modal,
  Form,
  Input,
  InputNumber,
  Descriptions,
  Timeline,
  Card
} from 'antd'
import {
  EyeOutlined,
  MoneyCollectOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  ClockCircleOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

// 申请人类型映射
const applicantTypeMap: Record<number, { text: string; color: string }> = {
  1: { text: '商户', color: 'blue' },
  2: { text: '运维人员', color: 'orange' }
}

// 提现状态映射
const withdrawStatusMap: Record<number, { text: string; color: string; icon: React.ReactNode }> = {
  1: { text: '待审核', color: 'warning', icon: <ClockCircleOutlined /> },
  2: { text: '待提现', color: 'processing', icon: <CheckCircleOutlined /> },
  3: { text: '已提现', color: 'success', icon: <CheckCircleOutlined /> },
  4: { text: '已驳回', color: 'error', icon: <CloseCircleOutlined /> },
  5: { text: '提现失败', color: 'error', icon: <CloseCircleOutlined /> }
}

// 格式化时间戳
const formatTime = (timestamp: number) => {
  if (!timestamp) {
    return '-'
  }
  return dayjs(timestamp * 1000).format('YYYY-MM-DD HH:mm:ss')
}

// 格式化金额
const formatMoney = (amount: number) => {
  return `¥${Number(amount || 0).toFixed(2)}`
}

const Withdrawal: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const formRef = useRef<ProFormInstance>()
  const [detailModalVisible, setDetailModalVisible] = useState(false)
  const [payoutModalVisible, setPayoutModalVisible] = useState(false)
  const [detailData, setDetailData] = useState<OrderManagementTypes.DetailWithdrawRes | null>(null)
  const [currentRecord, setCurrentRecord] = useState<OrderManagementTypes.WithdrawListDto | null>(
    null
  )
  const [payoutForm] = Form.useForm()
  const [confirmLoading, setConfirmLoading] = useState(false)

  // 查看详情
  const handleViewDetail = async (record: OrderManagementTypes.WithdrawListDto) => {
    try {
      const res = await getWithdrawDetail(record.id)
      if (res.code === ResultEnum.SUCCESS && res.data) {
        setDetailData(res.data)
        setDetailModalVisible(true)
      } else {
        message.error('获取详情失败')
      }
    } catch (e) {
      message.error('获取详情失败')
    }
  }

  // 打开确认打款弹窗
  const handleOpenPayout = (record: OrderManagementTypes.WithdrawListDto) => {
    setCurrentRecord(record)
    payoutForm.setFieldsValue({
      amount: record.amount,
      remark: ''
    })
    setPayoutModalVisible(true)
  }

  // 确认打款
  const handleConfirmPayout = async () => {
    try {
      if (!currentRecord) {
        return
      }

      setConfirmLoading(true)
      const res = await confirmPaymentWithdraw(currentRecord.id, {
        id: currentRecord.id
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('打款成功')
        setPayoutModalVisible(false)
        actionRef.current?.reload()
      } else {
        message.error(res.message || '打款失败')
      }
    } catch (e) {
      console.error(e)
    } finally {
      setConfirmLoading(false)
    }
  }

  // 表格列定义
  const columns: ProColumns<OrderManagementTypes.WithdrawListDto>[] = [
    {
      title: '提现单号',
      dataIndex: 'withdrawSn',
      key: 'withdrawSn',
      width: 180,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '申请人类型',
      dataIndex: 'applicantType',
      key: 'applicantType',
      width: 120,
      valueType: 'select',
      valueEnum: {
        '1': { text: '商户' },
        '2': { text: '运维人员' }
      },
      render: (_, record) => {
        const type = applicantTypeMap[record.applicantType]
        return <Tag color={type?.color || 'default'}>{type?.text || '未知'}</Tag>
      }
    },
    {
      title: '申请人名称',
      dataIndex: 'applicantName',
      key: 'applicantName',
      width: 140
    },
    {
      title: '联系电话',
      dataIndex: 'phone',
      key: 'phone',
      width: 140
    },
    {
      title: '提现金额',
      dataIndex: 'amount',
      key: 'amount',
      width: 120,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600, color: '#059669' }}>
          {formatMoney(text as number)}
        </span>
      )
    },
    {
      title: '可提现余额',
      dataIndex: 'availableAmount',
      key: 'availableAmount',
      width: 120,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{formatMoney(text as number)}</span>
      )
    },
    {
      title: '申请时间',
      dataIndex: 'applyTime',
      key: 'applyTime',
      width: 170,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, color: '#666' }}>{formatTime(text as number)}</span>
      )
    },
    {
      title: '订单状态',
      dataIndex: 'status',
      key: 'status',
      width: 120,
      valueType: 'select',
      valueEnum: {
        1: { text: '待审核' },
        2: { text: '待提现' },
        3: { text: '已提现' },
        4: { text: '已驳回' },
        5: { text: '提现失败' }
      },
      render: (_, record) => {
        const status = withdrawStatusMap[record.status]
        return (
          <Tag color={status?.color || 'default'} icon={status?.icon}>
            {status?.text || '未知'}
          </Tag>
        )
      }
    },
    {
      title: '审核人',
      dataIndex: 'auditUsername',
      key: 'auditUsername',
      width: 120,
      hideInSearch: true,
      render: text => text || '-'
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 100,
      render: (_, record) => [
        <Tooltip title="查看详情" key={`${record.id}-detail`}>
          <Button
            type="link"
            title="查看详情"
            icon={<EyeOutlined />}
            onClick={() => handleViewDetail(record)}
          />
        </Tooltip>,
        (record.status === 2 || record.status === 5) && (
          <Tooltip title="确认打款" key={`${record.id}-payout`}>
            <Button
              type="link"
              title="确认打款"
              icon={<MoneyCollectOutlined />}
              onClick={() => handleOpenPayout(record)}
            />
          </Tooltip>
        )
      ]
    }
  ]

  return (
    <>
      <ExcelTable
        key="withdrawal-list"
        formRef={formRef}
        columns={columns}
        requestFn={async params => {
          const { page, pageSize, withdrawSn, applicantType, applicantName, status, ...rest } =
            params
          return await getWithdrawList({
            page,
            pageSize,
            withdrawSn,
            applicantType,
            applicantName,
            status,
            ...rest
          })
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        toolBarRenderFn={() => []}
        scroll={{ x: 1400 }}
      />

      {/* 提现详情弹窗 */}
      <Modal
        title="提现详情"
        open={detailModalVisible}
        onCancel={() => setDetailModalVisible(false)}
        footer={[
          <Button key="close" onClick={() => setDetailModalVisible(false)}>
            关闭
          </Button>
        ]}
        width={720}
      >
        {detailData && (
          <Space direction="vertical" style={{ width: '100%' }} size="large">
            <Descriptions
              column={2}
              bordered
              size="small"
              labelStyle={{ background: '#F8FAFC', fontWeight: 500 }}
            >
              <Descriptions.Item label="提现单号">
                <span style={{ fontFamily: 'Courier New, monospace' }}>
                  {detailData.withdrawSn}
                </span>
              </Descriptions.Item>
              <Descriptions.Item label="申请人">
                <Tag color={applicantTypeMap[detailData.applicantType]?.color}>
                  {applicantTypeMap[detailData.applicantType]?.text}
                </Tag>
                <span style={{ marginLeft: 8 }}>{detailData.applicantName}</span>
              </Descriptions.Item>
              <Descriptions.Item label="联系电话">{detailData.phone}</Descriptions.Item>
              <Descriptions.Item label="订单状态">
                <Tag
                  color={withdrawStatusMap[detailData.status]?.color}
                  icon={withdrawStatusMap[detailData.status]?.icon}
                >
                  {withdrawStatusMap[detailData.status]?.text}
                </Tag>
              </Descriptions.Item>
              <Descriptions.Item label="提现金额">
                <span style={{ color: '#059669', fontWeight: 600, fontSize: 16 }}>
                  {formatMoney(detailData.amount)}
                </span>
              </Descriptions.Item>
              <Descriptions.Item label="可提现余额">
                {formatMoney(detailData.availableAmount)}
              </Descriptions.Item>
              <Descriptions.Item label="收款方式">微信商户号转账</Descriptions.Item>
              <Descriptions.Item label="审核人">
                {detailData.auditUsername || '-'}
              </Descriptions.Item>
            </Descriptions>

            <Card
              title={
                <Space>
                  <ClockCircleOutlined style={{ color: '#2563EB' }} />
                  <span>订单状态流转时间线</span>
                </Space>
              }
              size="small"
              style={{ background: '#F8FAFC' }}
            >
              <Timeline
                items={[
                  {
                    color: 'green',
                    children: (
                      <div>
                        <div style={{ fontSize: 13, color: '#64748B' }}>申请时间</div>
                        <div style={{ fontSize: 14, color: '#1E293B', fontWeight: 500 }}>
                          {formatTime(detailData.applyTime)}
                        </div>
                      </div>
                    )
                  },
                  {
                    color: detailData.auditTime ? 'green' : 'gray',
                    children: (
                      <div>
                        <div style={{ fontSize: 13, color: '#64748B' }}>审核时间</div>
                        <div style={{ fontSize: 14, color: '#1E293B', fontWeight: 500 }}>
                          {detailData.auditTime ? formatTime(detailData.auditTime) : '待审核'}
                        </div>
                      </div>
                    )
                  },
                  {
                    color: detailData.status === 3 ? 'green' : 'gray',
                    children: (
                      <div>
                        <div style={{ fontSize: 13, color: '#64748B' }}>提现时间</div>
                        <div style={{ fontSize: 14, color: '#1E293B', fontWeight: 500 }}>
                          {detailData.status === 3
                            ? formatTime(detailData.createdAt as unknown as number)
                            : '-'}
                        </div>
                      </div>
                    )
                  }
                ]}
              />
            </Card>
          </Space>
        )}
      </Modal>

      {/* 确认打款弹窗 */}
      <Modal
        title="确认提现打款"
        open={payoutModalVisible}
        onCancel={() => setPayoutModalVisible(false)}
        onOk={handleConfirmPayout}
        confirmLoading={confirmLoading}
        width={560}
      >
        <Form form={payoutForm} layout="vertical" style={{ marginTop: 16 }}>
          <Form.Item
            label="实际打款金额"
            name="amount"
            rules={[{ required: true, message: '请输入实际打款金额' }]}
          >
            <InputNumber
              style={{ width: '100%' }}
              min={0}
              step={0.01}
              precision={2}
              prefix="¥"
              placeholder="请输入实际打款金额"
            />
          </Form.Item>
          <Form.Item label="打款方式">
            <Input value="微信商户号转账（系统自动调用微信商户API）" disabled />
          </Form.Item>
          <Form.Item label="打款备注" name="remark">
            <Input.TextArea rows={3} placeholder="选填" />
          </Form.Item>
        </Form>
      </Modal>
    </>
  )
}

export default Withdrawal
